<?php require __DIR__.'/bootstrap.php';$u=require_client();$id=(int)($_GET['id']??0);$q=$pdo->prepare("SELECT * FROM private_documents WHERE id=? AND status='published'");$q->execute([$id]);$doc=$q->fetch();$levels=['basic'=>1,'premium'=>2,'ultimate'=>3];if(!$doc||$levels[user_plan((int)$u['id'])]<$levels[$doc['minimum_plan']]){http_response_code(403);exit;} $path=__DIR__.'/'.$doc['file_path'];if(!is_file($path)){http_response_code(404);exit;}header('Content-Type: application/pdf');header('Content-Disposition: inline; filename="documento.pdf"');header('Cache-Control: private, no-store, max-age=0');readfile($path);
